// Generate waveform bars
function fillWaveform(id, count) { const c=document.getElementById(id); for(let i=0;i{const wrap=document.createElement('div');wrap.style.cssText='flex:1;display:flex;flex-direction:column;align-items:center';const bar=document.createElement('div');bar.style.cssText='width:100%;background:var(--brand-primary);border-radius:3px 3px 0 0;opacity:0.8';bar.style.height=v*10+'px';const lbl=document.createElement('div');lbl.className='bar-label';lbl.textContent=labels[i];wrap.appendChild(bar);wrap.appendChild(lbl);c.appendChild(wrap)}); }
fillChart('chart1',[2,4,3,6,5,8],['Mar','Apr','May','Jun','Jul','Aug']);
fillChart('chart2',[1,3,2,4,3,5],['Mar','Apr','May','Jun','Jul','Aug']);
